const listWorkItemsForWorkspace = `-- name: ListWorkItemsForWorkspace :many
SELECT
    id,
    workspace_id,
    user_story_id,
    parent_id,
    title,
    description,
    item_type,
    status,
    priority,
    assignee_id,
    reporter_id,
    sprint_id,
    due_date,
    story_points,
    created_at,
    updated_at,
    deleted_at
FROM work_items
WHERE workspace_id = $1
  AND deleted_at IS NULL
ORDER BY created_at DESC
`

func (q *Queries) ListWorkItemsForWorkspace(ctx context.Context, workspaceID pgtype.UUID) ([]WorkItem, error) {
	rows, err := q.db.Query(ctx, listWorkItemsForWorkspace, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkItem
	for rows.Next() {
		var i WorkItem
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.UserStoryID,
			&i.ParentID,
			&i.Title,
			&i.Description,
			&i.ItemType,
			&i.Status,
			&i.Priority,
			&i.AssigneeID,
			&i.ReporterID,
			&i.SprintID,
			&i.DueDate,
			&i.StoryPoints,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const removeWorkItemLabel = `-- name: RemoveWorkItemLabel :one
DELETE FROM work_item_labels wil
USING work_items wi, labels l
WHERE wil.work_item_id = $1::uuid
  AND wil.label_id = $2::uuid
  AND wi.id = wil.work_item_id
  AND wi.workspace_id = $3::uuid
  AND wi.deleted_at IS NULL
  AND l.id = wil.label_id
  AND l.workspace_id = $3::uuid
RETURNING wil.work_item_id, wil.label_id, wil.created_at
`

